/**
 * Admins see all shipments. Regular users see only their own.
 * @summary List shipments
 */
export const getListShipmentsUrl = (params?: ListShipmentsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/shipments?${stringifiedParams}`
    : `/api/shipments`;
};

export const listShipments = async (
  params?: ListShipmentsParams,
  options?: RequestInit,
): Promise<ShipmentPage> => {
  return customFetch<ShipmentPage>(getListShipmentsUrl(params), {
    ...options,
    method: "GET",
  });
};

